const require_browser = require("../utils/browser.js");
const require_defaults = require("../utils/defaults.js");
const require_index = require("../useDeepCompareEffect/index.js");
let react = require("react");
//#region src/useKeyModifier/index.ts
const defaultEvents = [
	"mousedown",
	"mouseup",
	"keydown",
	"keyup"
];
const useKeyModifier = (modifier, options = require_defaults.defaultOptions) => {
	const { events = defaultEvents, initial = false } = options;
	const [state, setState] = (0, react.useState)(initial);
	require_index.useDeepCompareEffect(() => {
		const handler = (evt) => {
			const event = evt;
			if (typeof event.getModifierState === "function") setState(event.getModifierState(modifier));
		};
		events.forEach((listenEvent) => require_browser.on(document, listenEvent, handler));
		return () => {
			events.forEach((listenEvent) => require_browser.off(document, listenEvent, handler));
		};
	}, [modifier, events]);
	return state;
};
//#endregion
exports.useKeyModifier = useKeyModifier;
